<?php declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/includes/auth.php';$db=db();$e=fn($v)=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');if($_SERVER['REQUEST_METHOD']==='POST'){$n='TKT-'.date('YmdHis').'-'.random_int(100,999);$q=$db->prepare('INSERT INTO support_tickets(ticket_number,client_id,project_id,assigned_staff_id,subject,description,category,priority,status,due_at) VALUES(?,?,?,?,?,?,?,?,?,?)');$q->execute([$n,$_POST['client_id']?:null,$_POST['project_id']?:null,$_POST['assigned_staff_id']?:null,trim($_POST['subject']),trim($_POST['description']??''),trim($_POST['category']??''),$_POST['priority'],'open',null]);header('Location: support.php');exit;}$rows=$db->query('SELECT t.*,CONCAT(s.first_name," ",s.last_name) staff_name,c.name client_name FROM support_tickets t LEFT JOIN staff_members s ON s.id=t.assigned_staff_id LEFT JOIN clients c ON c.id=t.client_id ORDER BY FIELD(t.status,"open","in_progress","waiting_client","resolved","closed"),t.created_at DESC')->fetchAll();$staff=$db->query("SELECT id,first_name,last_name FROM staff_members WHERE employment_status='active' ORDER BY first_name")->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Support Desk</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-4"><h1 class="h3">Support Desk</h1><div class="card mb-4"><div class="card-body"><form method="post" class="row g-2"><div class="col-md-4"><input class="form-control" name="subject" placeholder="Subject" required></div><div class="col-md-2"><input class="form-control" type="number" name="client_id" placeholder="Client ID"></div><div class="col-md-2"><input class="form-control" type="number" name="project_id" placeholder="Project ID"></div><div class="col-md-2"><select class="form-select" name="priority"><option>low</option><option selected>medium</option><option>high</option><option>urgent</option></select></div><div class="col-md-2"><select class="form-select" name="assigned_staff_id"><option value="">Unassigned</option><?php foreach($staff as $s):?><option value="<?=$s['id']?>"><?=$e($s['first_name'].' '.$s['last_name'])?></option><?php endforeach;?></select></div><div class="col-md-3"><input class="form-control" name="category" placeholder="Category"></div><div class="col-md-9"><input class="form-control" name="description" placeholder="Description"></div><div class="col-12"><button class="btn btn-dark">Create Ticket</button></div></form></div></div><div class="card"><div class="card-body"><table class="table"><thead><tr><th>Ticket</th><th>Client</th><th>Subject</th><th>Priority</th><th>Status</th><th>Assigned</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$e($r['ticket_number'])?></td><td><?=$e($r['client_name'])?></td><td><?=$e($r['subject'])?></td><td><?=$e($r['priority'])?></td><td><?=$e($r['status'])?></td><td><?=$e($r['staff_name'])?></td></tr><?php endforeach;?></tbody></table></div></div></main></body></html>